<style>.partner-hero{padding:56px max(20px,calc((100% - 1120px)/2));background:#f8f7f4;border-bottom:1px solid #e5e5e5}.partner-content{max-width:1120px;margin:auto;padding:38px 20px;display:grid;grid-template-columns:minmax(0,2fr) minmax(260px,1fr);gap:32px}.partner-mark{width:76px;height:76px;object-fit:cover;background:#eee}.partner-courses{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px}.partner-course{border:1px solid #e5e5e5;padding:18px}.provider-tag{font-size:.72rem;text-transform:uppercase;color:#666;letter-spacing:.05em}.partner-enquiry{border:1px solid #e5e5e5;padding:20px;height:max-content;background:#fff}.partner-enquiry label{display:grid;gap:5px;margin:10px 0;font-size:.8rem;font-weight:600}.partner-enquiry input,.partner-enquiry textarea,.partner-enquiry select{padding:10px;border:1px solid #ddd;font:inherit;width:100%}@media(max-width:720px){.partner-content{grid-template-columns:1fr}.partner-hero{padding:38px 20px}}</style>
<header class="partner-hero"><div style="max-width:1120px;margin:auto"><?php if($partner['cover_path']): ?><img src="<?= e(base_url('/'.ltrim($partner['cover_path'],'/'))) ?>" alt="" style="width:100%;max-height:260px;object-fit:cover;margin-bottom:20px"><?php endif ?><div style="display:flex;align-items:center;gap:16px"><?php if($partner['logo_path']): ?><img class="partner-mark" src="<?= e(base_url('/'.ltrim($partner['logo_path'],'/'))) ?>" alt="<?= e($partner['display_name']) ?> logo"><?php else: ?><div class="partner-mark" style="display:grid;place-items:center"><i class="bi bi-building"></i></div><?php endif ?><div><div style="font-size:.72rem;letter-spacing:.1em;color:#527329"><i class="bi bi-patch-check-fill"></i> APPROVED PARTNER</div><h1 style="margin:4px 0;font-size:clamp(1.8rem,4vw,2.7rem)"><?= e($partner['display_name']) ?></h1><div style="color:#666"><?= e($partner['city']??'') ?><?= $partner['state']?', '.e($partner['state']):'' ?></div></div></div></div></header>
<main class="partner-content"><div><section><h2>About the institution</h2><p style="line-height:1.7;color:#555"><?= nl2br(e($partner['description']??'Institution profile')) ?></p><?php if($partner['address']): ?><p><?= e($partner['address']) ?></p><?php endif ?><?php if($partner['map_url']): ?><a href="<?= e($partner['map_url']) ?>" rel="noopener" target="_blank">View location</a><?php endif ?></section><section style="margin-top:34px"><h2>Courses offered by <?= e($partner['display_name']) ?></h2><div class="partner-courses"><?php if(!$courses): ?><p>There are no published independent courses at the moment.</p><?php else: foreach($courses as $course): ?><article class="partner-course"><div class="provider-tag">Delivered by <?= e($partner['display_name']) ?></div><h3><?= e($course['title']) ?></h3><p style="color:#666"><?= e(mb_strimwidth((string)$course['description'],0,180,'…')) ?></p><p><?= e($course['duration']??'') ?> · <?= e($course['delivery_mode']??'') ?></p><?php if($course['current_fee']!==null): ?><strong>₹<?= number_format((float)$course['current_fee'],2) ?></strong><?php endif ?></article><?php endforeach; endif ?></div></section></div>
<aside class="partner-enquiry"><h2>Enquire with the institution</h2><p style="font-size:.85rem;color:#666">Share your contact details so the institution can follow up.</p><form method="post" action="<?= base_url('/partners/'.rawurlencode($partner['slug']).'/enquiry') ?>"><?= csrf_field() ?><label>Your name<input name="name" required></label><label>Email<input type="email" name="email" required></label><label>Phone<input name="phone"></label><label>Course<select name="course_id"><option value="">General enquiry</option><?php foreach($courses as $course): ?><option value="<?= (int)$course['id'] ?>"><?= e($course['title']) ?></option><?php endforeach ?></select></label><label>Message<textarea name="message" rows="3"></textarea></label><label style="display:flex;grid-template-columns:auto 1fr;align-items:start"><input type="checkbox" name="consent" value="1" required style="width:auto"> I consent to share these details with this institution.</label><button class="tcm-btn primary" style="width:100%">Send enquiry</button></form></aside></main>
